// Generated by packages/academy/scripts/build-content.ts. Don't edit by hand.
export default JSON.parse("{\"3.7.1\":{\"unit\":\"3.7\",\"courseId\":\"3.7.1\",\"hook\":{\"prompt\":\"The LCB's rule: 2.00 + inflation + 0.5 × (inflation − 2.00) − 0.5 × (unemployment − 4.50). Inflation is 3.00% and unemployment 4.50%. What rate does the rule prescribe?\",\"control\":{\"kind\":\"slider\",\"min\":3,\"max\":7,\"step\":0.25,\"unit\":\"%\",\"start\":4,\"answer\":5.5,\"tolerance\":0,\"feedback\":[{\"from\":3,\"to\":4.75,\"text\":\"Too low: 2.00 + 3.00 is already 5.00, before the inflation gap adds 0.5 × 1.00.\"},{\"from\":5,\"to\":5.25,\"text\":\"Close. 2.00 + 3.00 = 5.00; now add half the inflation gap, 0.5 × (3.00 − 2.00).\"},{\"from\":5.5,\"to\":5.5,\"text\":\"Right: 2.00 + 3.00 + 0.50 − 0 = 5.50%.\"},{\"from\":5.75,\"to\":7,\"text\":\"Too high. Unemployment sits at its 4.50% benchmark, so that term adds nothing: 5.50%.\"}]},\"compare\":\"You said {yours}. The rule gives 2.00 + 3.00 + 0.5 × 1.00 − 0.5 × 0 = 5.50%, well above the LCB's 4.00% today.\",\"concept\":\"reaction-function\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Mandates and reaction functions\",\"text\":\"Central banks work to mandates. The Fed has two goals, maximum employment and stable prices, with a 2% inflation target. The ECB, the Bank of England and the Bank of Japan put price stability first, each with a 2% target. A [[reaction-function]] describes how a bank turns data into decisions. The LCB's rule is synthetic, shaped like a [[taylor-rule]].\"},{\"kind\":\"worked\",\"title\":\"The rule, worked\",\"lines\":[\"Inflation 2.60%, unemployment 5.10%. Target 2.00%; unemployment benchmark 4.50%.\",\"Base: 2.00 + 2.60 = 4.60.\",\"Inflation gap: +0.5 × (2.60 − 2.00) = +0.30.\",\"Unemployment gap: −0.5 × (5.10 − 4.50) = −0.30.\",\"Prescribed rate = ?\"],\"ask\":{\"answer\":4.6,\"tolerance\":0.001,\"unit\":\"%\",\"feedback\":[{\"value\":4.9,\"text\":\"You left out the unemployment term. Unemployment above 4.50% pulls the rate down: −0.30.\"},{\"value\":5.2,\"text\":\"Check the sign: unemployment above its benchmark lowers the rate, so subtract 0.30.\"},{\"value\":4.3,\"text\":\"You left out the inflation gap: +0.30.\"}],\"correct\":\"Right: 4.60%. The two gaps cancel out.\"},\"after\":\"Inflation above target pushes up exactly as much as unemployment above its benchmark pulls down. With the LCB at 4.00%, the rule still points to hikes. The market's question is how fast.\",\"concept\":\"reaction-function\"},{\"kind\":\"figure\",\"title\":\"From data to prices\",\"figure\":{\"kind\":\"flow\",\"start\":\"data\",\"nodes\":[{\"id\":\"data\",\"text\":\"Data: inflation, jobs, financial conditions\",\"kind\":\"end\"},{\"id\":\"rf\",\"text\":\"Reaction function: what the LCB does with them\",\"kind\":\"end\"},{\"id\":\"path\",\"text\":\"Expected path: the rate after each of the next 4 meetings\",\"kind\":\"end\"},{\"id\":\"lb2\",\"text\":\"LB2, the 2-year yield: roughly the average of that path\",\"kind\":\"end\"},{\"id\":\"assets\",\"text\":\"vUSD, LABX and the rest, priced off rates\",\"kind\":\"end\"}],\"steps\":[\"A hot inflation print arrives.\",\"Through the reaction function, it raises the prescribed rate.\",\"The market lifts the expected rate at every coming meeting, not only the next.\",\"LB2 rises with the path; the currency and stocks reprice.\"]},\"text\":\"A surprise matters through the [[expected-policy-path]] it implies. That's why one inflation print can move a 2-year yield far more than the next meeting alone would justify.\",\"concept\":\"expected-policy-path\"},{\"kind\":\"predict\",\"title\":\"The bank changes its weights\",\"prompt\":\"The LCB starts weighing unemployment more and inflation less. The same hot inflation print arrives as last month. Does LB2 move more or less than last time?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"more\",\"label\":\"More\",\"feedback\":\"A smaller inflation weight means each hot print adds less to the prescribed rate, so LB2 moves less.\"},{\"id\":\"less\",\"label\":\"Less\",\"feedback\":\"Right.\"},{\"id\":\"same\",\"label\":\"The same\",\"feedback\":\"The print is the same, but the rule that turns it into rates has changed.\"}],\"answer\":\"less\"},\"reveal\":\"Less. Before, a print 0.30 hotter added 1.5 × 0.30 = 0.45 to the prescribed rate. Now inflation counts 1.25 times: 0.375. Every future meeting reprices by less, so LB2 does too. The change itself is news: once the market spots it, the whole path reprices at once.\",\"concept\":\"reaction-function\"},{\"kind\":\"match\",\"title\":\"Who aims at what\",\"prompt\":\"Sort each bank by its mandate. The LCB's rule weighs both inflation and unemployment.\",\"pairs\":[{\"left\":\"Fed\",\"right\":\"Dual: jobs and prices\",\"wrong\":\"The Fed's mandate names two goals: maximum employment and stable prices.\"},{\"left\":\"ECB\",\"right\":\"Price stability first\",\"wrong\":\"The ECB's primary objective is price stability, with a 2% target over the medium term.\"},{\"left\":\"Bank of England\",\"right\":\"Price stability first\",\"wrong\":\"The Bank of England puts price stability first, with an inflation target set by the government.\"},{\"left\":\"Bank of Japan\",\"right\":\"Price stability first\",\"wrong\":\"The Bank of Japan's mandate is price stability, with a 2% target.\"},{\"left\":\"LCB (synthetic)\",\"right\":\"Dual: jobs and prices\",\"wrong\":\"The LCB's rule has an unemployment term as well as inflation, so it behaves like a dual mandate.\"}],\"columns\":[\"Bank\",\"Mandate\"],\"correct\":\"Right. A mandate tells you which data the reaction function weighs. Price-stability banks still watch jobs, for what they mean for inflation.\",\"concept\":\"reaction-function\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"The rule is a model, not the bank. Real central banks don't follow a formula, and weights estimated from past decisions drift. An old estimate is a risk, not a certainty: when the bank's behaviour changes, the market reprices before your model does.\"},{\"kind\":\"predict\",\"title\":\"Your turn: estimate the weights\",\"prompt\":\"The LCB's last three decisions. Inflation 3.00%, unemployment 4.50%: 5.25%. Inflation 2.00%, unemployment 5.50%: 3.00%. Inflation 2.40%, unemployment 5.00%: 4.00%. Which weights on the inflation gap and the unemployment gap fit?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"0.5 and 0.5, the published rule\",\"feedback\":\"That rule gives 5.50%, 3.50% and 4.35%: too high every time.\"},{\"id\":\"b\",\"label\":\"1.0 and 0\",\"feedback\":\"That rule gives 6.00%, 4.00% and 4.80%. It ignores jobs and misses every decision.\"},{\"id\":\"c\",\"label\":\"0.25 and 1.0\",\"feedback\":\"Right.\"}],\"answer\":\"c\"},\"reveal\":\"0.25 and 1.0 fit all three: 5.25%, 3.00% and 4.00%. Since the published rule, the LCB has weighed unemployment more. A real estimate uses many more meetings, and still carries error.\",\"concept\":\"reaction-function\"},{\"kind\":\"worked\",\"title\":\"Predict meeting 13\",\"lines\":[\"Fitted rule: 2.00 + inflation + 0.25 × (inflation − 2.00) − 1.0 × (unemployment − 4.50).\",\"Next meeting: inflation 3.20%, unemployment 4.80%.\",\"Your prediction for the prescribed rate = ?\"],\"ask\":{\"answer\":5.2,\"tolerance\":0.25,\"unit\":\"%\",\"feedback\":[{\"value\":5.65,\"text\":\"That's the published rule. The recent decisions fit 0.25 and 1.0.\"},{\"value\":6.4,\"text\":\"That's the rule that ignores jobs. The recent decisions fit 0.25 and 1.0.\"}],\"correct\":\"Right: 2.00 + 3.20 + 0.30 − 0.30 = 5.20%. Within 25 bp of the rule counts as a good model.\"},\"after\":\"Write your number down before each meeting, next to what LRF prices (3.7.2). The gap between the two is your view; the market already has its own.\",\"concept\":\"reaction-function\"}],\"check\":[\"q-3.7.1-1\",\"q-3.7.1-2\",\"q-3.7.1-3\"],\"recap\":{\"takeaways\":[\"A rule turns data into a rate: 2.00 + 3.00 + 0.5 × 1.00 = 5.50%.\",\"Estimate the weights from past decisions, then predict the next one. Weights drift, so re-check them.\",\"A new reaction function reprices every future meeting, so the 2-year yield moves, not just the next decision.\"]}},\"3.7.2\":{\"unit\":\"3.7\",\"courseId\":\"3.7.2\",\"hook\":{\"prompt\":\"Futures imply an average rate of 4.05% for a 30-day month with a meeting on day 16. The rate is 4.00% now. What is the chance of a 25 bp hike?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":100,\"step\":5,\"unit\":\"%\",\"start\":50,\"answer\":40,\"tolerance\":5,\"feedback\":[{\"from\":0,\"to\":10,\"text\":\"Too low. Futures price an average above today's 4.00%, so a hike has a real chance.\"},{\"from\":15,\"to\":30,\"text\":\"Too low. The naive formula, 0.05 ÷ 0.25, gives 20%, but half the month passes before the meeting, at 4.00%.\"},{\"from\":35,\"to\":45,\"text\":\"About right: 40%. The first 15 days dilute the move by half.\"},{\"from\":50,\"to\":100,\"text\":\"Too high. Only the last 15 days carry the new rate: 40%.\"}]},\"compare\":\"You said {yours}. The first 15 days stay at 4.00%, so the last 15 must average 4.10%: a 40% chance of a 25 bp hike.\",\"concept\":\"implied-policy-probability\"},\"learn\":[{\"kind\":\"worked\",\"title\":\"From price to rate\",\"lines\":[\"LRF, the LCB's [[rate-futures]] contract, is quoted as 100 minus the month's average policy rate.\",\"This month's LRF: 95.95.\",\"Implied average rate = 100 − 95.95 = ?\"],\"ask\":{\"answer\":4.05,\"tolerance\":0.001,\"unit\":\"%\",\"feedback\":[{\"value\":95.95,\"text\":\"That's the price. Subtract it from 100.\"}],\"correct\":\"Right: 4.05%.\"},\"after\":\"That's the [[implied-rate]]. Price and rate move in opposite directions: when hikes get priced in, LRF falls. And it's the month's average, not the rate after the meeting.\",\"concept\":\"implied-policy-probability\"},{\"kind\":\"worked\",\"title\":\"Weight the days\",\"lines\":[\"30-day month, meeting on day 16. Days 1–15 at today's 4.00%; days 16–30 at the new rate r.\",\"Rate-days in the month: 4.05 × 30 = 121.5.\",\"Days 1–15: 15 × 4.00 = 60.\",\"r = (121.5 − 60) ÷ 15 = 4.10%.\",\"Hike probability = (4.10 − 4.00) ÷ 0.25, in % = ?\"],\"ask\":{\"answer\":40,\"tolerance\":0.5,\"unit\":\"%\",\"feedback\":[{\"value\":20,\"text\":\"That uses the month's average, 4.05. Use r, 4.10: the rate after the meeting.\"},{\"value\":0.4,\"text\":\"As a fraction, yes. Give it in %: 40.\"}],\"correct\":\"Right: 40%.\"},\"after\":\"That's the [[implied-probability]] of a hike. The expected rate after the meeting, 4.10%, sits 40% of the way from a hold, 4.00%, to a hike, 4.25%.\",\"concept\":\"implied-policy-probability\"},{\"kind\":\"predict\",\"title\":\"The naive shortcut\",\"prompt\":\"The naive formula, (4.05 − 4.00) ÷ 0.25, gives 20%. Which is right, and why?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"naive\",\"label\":\"20%: futures price the month's average\",\"feedback\":\"They do, but half that month passes before the meeting, still at 4.00%.\"},{\"id\":\"weighted\",\"label\":\"40%: the days before the meeting dilute the average\",\"feedback\":\"Right.\"},{\"id\":\"both\",\"label\":\"Both: they answer different questions\",\"feedback\":\"Only one is the chance of a hike at this meeting: 40%.\"}],\"answer\":\"weighted\"},\"reveal\":\"40%. Fifteen days at the old rate halve the move in the monthly average, so the naive formula halves the probability. The later the meeting falls in the month, the bigger the error.\",\"concept\":\"implied-policy-probability\"},{\"kind\":\"explain\",\"title\":\"How the tools do it\",\"text\":\"Published probability tools follow the same logic. They assume moves in 25 bp steps, chain the months so each starts where the last ended, and can use the next month's contract when a meeting falls late in the month. [[ois|OIS]] rates give a second reading of the same expectations. Both are prices, so read them as prices.\"},{\"kind\":\"predict\",\"title\":\"A meeting on day 28\",\"prompt\":\"Same month, but the meeting is on day 28: only 3 days carry the new rate. LRF moves by one hundredth, from 95.99 to 95.98. How much does the implied hike probability change?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"small\",\"label\":\"About 4 points\",\"feedback\":\"With only 3 days after the meeting, each 0.01 in the monthly average moves r by 0.10.\"},{\"id\":\"big\",\"label\":\"About 40 points\",\"feedback\":\"Right.\"},{\"id\":\"none\",\"label\":\"Not at all\",\"feedback\":\"The average changed by 0.01, and only 3 days have to absorb it.\"}],\"answer\":\"big\"},\"reveal\":\"From 40% to 80%. With 3 days left, r = (30 × average − 27 × 4.00) ÷ 3, so each 0.01 in the average moves r by 0.10. That's why the next month's contract gives a steadier reading.\",\"concept\":\"implied-policy-probability\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"60% is not a certainty. An implied probability is a price, not a poll: it includes risk premia and can swing late, in the quiet period before a meeting when policymakers stop speaking. Your only edge is the gap between your view and what is already priced.\"},{\"kind\":\"worked\",\"title\":\"Your turn: a later meeting\",\"lines\":[\"LRF trades at 95.97. The rate is 4.00%.\",\"30-day month, meeting on day 21: days 1–20 at 4.00%, days 21–30 at the new rate r.\",\"Implied average: 100 − 95.97 = 4.03%.\",\"Find r, then the chance of a 25 bp hike, in % = ?\"],\"ask\":{\"answer\":36,\"tolerance\":1,\"unit\":\"%\",\"feedback\":[{\"value\":12,\"text\":\"That's the naive formula. Weight the days: only 10 carry the new rate.\"},{\"value\":4.09,\"text\":\"That's r. Now (4.09 − 4.00) ÷ 0.25, in %.\"}],\"correct\":\"Right: 4.03 × 30 = 120.9; 120.9 − 80 = 40.9; r = 40.9 ÷ 10 = 4.09; 0.09 ÷ 0.25 = 36%.\"},\"after\":\"The naive formula says 12%, a third of the true figure. Before any meeting, write your own probability next to the market's.\",\"concept\":\"implied-policy-probability\"}],\"check\":[\"q-3.7.2-1\",\"q-3.7.2-2\",\"q-3.7.2-3\"],\"recap\":{\"takeaways\":[\"Implied rate = 100 − futures price: 100 − 95.95 = 4.05%.\",\"Weight the days: with the meeting on day 16, a 4.05% average means a 40% hike chance.\",\"An implied probability is a price with risk premia. Your edge is only your view minus it.\"]}},\"3.7.3\":{\"unit\":\"3.7\",\"courseId\":\"3.7.3\",\"hook\":{\"prompt\":\"The LCB holds rates, as expected. Two of nine members vote for a hike; the market expected a unanimous hold. Hawkish, dovish or neutral?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"hawk\",\"label\":\"Hawkish\",\"feedback\":\"Right. Two hike votes show where the next move may go, and the market expected none.\"},{\"id\":\"dove\",\"label\":\"Dovish\",\"feedback\":\"The hold was expected. The two hike votes weren't, and they tilt the next move up.\"},{\"id\":\"neutral\",\"label\":\"Neutral\",\"feedback\":\"The decision matched expectations, but the vote didn't: two members already want to hike.\"}],\"answer\":\"hawk\"},\"compare\":\"You chose {yours}. The decision matched; the vote didn't. Two dissents for a hike, against an expected unanimous hold, read hawkish: the next move is more likely up.\",\"concept\":\"policy-communication\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Read the edits\",\"text\":\"Put the new [[policy-statement]] next to the last one. Last: 'Some further firming may be appropriate. The risks are balanced.' Now: 'Further firming may be appropriate. The risks to inflation are **tilted to the upside**.' Two edits: '**some**' is gone, and the risks now lean hawkish. Desks read the changes, not the whole text.\"},{\"kind\":\"explain\",\"title\":\"The tone scale\",\"text\":\"Score each edit from −2 to +2. **±2**: it adds or removes a bias toward the next move, such as a promise of further hikes. **±1**: it shifts the balance of risks, the timing or the strength of a phrase. **0**: it restates data with no new policy signal. Plus means [[hawkish]]; minus, [[dovish]].\"},{\"kind\":\"explain\",\"title\":\"Votes and dissents\",\"text\":\"A [[vote-split]] shows the spread of views on the committee. A [[dissent]] for a hike at a hold says where the next move may go, and who might join next time. Splits can run three ways: some for a big cut, most for a small one, a few for no change. Count them against what was expected.\"},{\"kind\":\"predict\",\"title\":\"Synthetic replay: nothing changed\",\"prompt\":\"The market expected the LCB to drop 'for an extended period', a hawkish edit. The statement keeps the phrase, word for word. How does LB2 react?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"up\",\"label\":\"Rises\",\"feedback\":\"An unchanged phrase sounds neutral, but the market had priced the hawkish edit. Its absence is dovish.\"},{\"id\":\"down\",\"label\":\"Falls\",\"feedback\":\"Right.\"},{\"id\":\"flat\",\"label\":\"Barely moves: nothing changed\",\"feedback\":\"That holds only if nothing was expected. Here a change was priced, and it didn't come.\"}],\"answer\":\"down\"},\"reveal\":\"LB2 falls. The hawkish edit was in the price; the unchanged text took it back out. Unchanged words are news when a change was expected, and the same logic applies to any real statement.\",\"concept\":\"policy-communication\"},{\"kind\":\"explain\",\"title\":\"Minutes, three weeks later\",\"text\":\"The LCB's [[minutes]] arrive three weeks after the meeting and show the debate behind the statement. Quantifiers carry the signal: 'many participants' saw further hikes as likely is stronger than 'a few participants'. Minutes can confirm the first reading or reverse it, so a statement's move is not the last word.\"},{\"kind\":\"predict\",\"title\":\"Tone against the price\",\"prompt\":\"You score today's statement +1 overall: mildly hawkish. Before the release, the market had priced a tone of +2. Which way does LB2 move?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"up\",\"label\":\"Up: the statement is hawkish\",\"feedback\":\"It's hawkish in absolute terms, but less hawkish than the +2 that was priced.\"},{\"id\":\"down\",\"label\":\"Down: it's less hawkish than priced\",\"feedback\":\"Right.\"},{\"id\":\"none\",\"label\":\"No move: hawkish was expected\",\"feedback\":\"The market expected +2 and got +1. That gap is a surprise, and LB2 trades it.\"}],\"answer\":\"down\"},\"reveal\":\"Down. What moves price is tone minus priced tone: +1 − (+2) = −1, a dovish surprise. A hawkish statement can still push yields lower when the market expected more.\",\"concept\":\"policy-communication\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"Algorithms compare statements within seconds. Your edge isn't speed: it's reading tone against what was priced, then deciding calmly, by your plan, what it means for the path.\"}],\"task\":{\"widget\":\"bias-spotter\",\"data\":{\"options\":[{\"id\":\"m2\",\"label\":\"−2 · very dovish\"},{\"id\":\"m1\",\"label\":\"−1 · dovish\"},{\"id\":\"z\",\"label\":\"0 · neutral\"},{\"id\":\"p1\",\"label\":\"+1 · hawkish\"},{\"id\":\"p2\",\"label\":\"+2 · very hawkish\"}],\"cards\":[{\"id\":\"a\",\"text\":\"'Spending grew at a moderate pace' becomes 'Spending **continued to grow** at a moderate pace.'\",\"answer\":\"z\",\"correct\":\"0. Same data, same pace: an editorial change with no policy signal.\",\"rationales\":{\"m2\":\"−2 is for removing a bias toward hikes, or adding one toward cuts. Here the pace is unchanged: the edit restates the data.\",\"m1\":\"−1 is for a dovish shift in risks, timing or strength, with no new bias. Here the pace is unchanged: the edit restates the data.\",\"p1\":\"+1 is for a hawkish shift in risks, timing or strength, with no new bias. Here the pace is unchanged: the edit restates the data.\",\"p2\":\"+2 is for adding a bias toward hikes, or removing one toward cuts. Here the pace is unchanged: the edit restates the data.\"}},{\"id\":\"b\",\"text\":\"New sentence: '**Further increases** in the policy rate will likely be needed.'\",\"answer\":\"p2\",\"correct\":\"+2. It adds a bias: the next move is more likely a hike.\",\"rationales\":{\"m2\":\"−2 is for removing a bias toward hikes, or adding one toward cuts. Here a new sentence points the next move up.\",\"m1\":\"−1 is for a dovish shift in risks, timing or strength, with no new bias. Here a new sentence points the next move up.\",\"z\":\"0 is for wording that restates the data with no policy signal. Here a new sentence points the next move up.\",\"p1\":\"+1 is for a hawkish shift in risks, timing or strength, with no new bias. Here a new sentence points the next move up.\"}},{\"id\":\"c\",\"text\":\"'Inflation remains high' becomes 'Inflation **has eased** but remains elevated.'\",\"answer\":\"m1\",\"correct\":\"−1. It acknowledges progress on inflation: a dovish shift in strength, with no new bias.\",\"rationales\":{\"m2\":\"−2 is for removing a bias toward hikes, or adding one toward cuts. Here the bank acknowledges progress on inflation but sets no new direction.\",\"z\":\"0 is for wording that restates the data with no policy signal. Here the bank acknowledges progress on inflation but sets no new direction.\",\"p1\":\"+1 is for a hawkish shift in risks, timing or strength, with no new bias. Here the bank acknowledges progress on inflation but sets no new direction.\",\"p2\":\"+2 is for adding a bias toward hikes, or removing one toward cuts. Here the bank acknowledges progress on inflation but sets no new direction.\"}},{\"id\":\"d\",\"text\":\"'The risks are balanced' becomes 'The risks to inflation are **tilted to the upside**.'\",\"answer\":\"p1\",\"correct\":\"+1. The balance of risks shifts hawkish, with no promise about the next move.\",\"rationales\":{\"m2\":\"−2 is for removing a bias toward hikes, or adding one toward cuts. Here only the balance of risks moves, toward higher inflation.\",\"m1\":\"−1 is for a dovish shift in risks, timing or strength, with no new bias. Here only the balance of risks moves, toward higher inflation.\",\"z\":\"0 is for wording that restates the data with no policy signal. Here only the balance of risks moves, toward higher inflation.\",\"p2\":\"+2 is for adding a bias toward hikes, or removing one toward cuts. Here only the balance of risks moves, toward higher inflation.\"}},{\"id\":\"e\",\"text\":\"Deleted: '**Some further firming** may be appropriate.'\",\"answer\":\"m2\",\"correct\":\"−2. The bias toward further hikes is gone.\",\"rationales\":{\"m1\":\"−1 is for a dovish shift in risks, timing or strength, with no new bias. Here a sentence pointing the next move up disappears.\",\"z\":\"0 is for wording that restates the data with no policy signal. Here a sentence pointing the next move up disappears.\",\"p1\":\"+1 is for a hawkish shift in risks, timing or strength, with no new bias. Here a sentence pointing the next move up disappears.\",\"p2\":\"+2 is for adding a bias toward hikes, or removing one toward cuts. Here a sentence pointing the next move up disappears.\"}}]},\"goal\":\"Score five edits between pairs of synthetic LCB statements, from −2 (very dovish) to +2 (very hawkish), with this lesson's scale.\",\"success\":{\"field\":\"solved\",\"eq\":5},\"correct\":\"Five scored. Add up a statement's edits and compare the total with the tone that was priced: only the difference moves price.\",\"hints\":[\"±2 adds or removes a bias toward the next move. ±1 shifts risks, timing or strength. 0 restates data.\",\"Removing a hawkish line is dovish, and the other way round.\"],\"showMe\":{\"solved\":5},\"concept\":\"policy-communication\"},\"check\":[\"q-3.7.3-1\",\"q-3.7.3-2\",\"q-3.7.3-3\"],\"recap\":{\"takeaways\":[\"Read statements as edits: score each change from −2 to +2 by what it does to the next move.\",\"Dissents show where the next move may go; count them against the vote the market expected.\",\"Price moves on tone minus priced tone: +1 against +2 priced is a dovish surprise.\"]}},\"3.7.4\":{\"unit\":\"3.7\",\"courseId\":\"3.7.4\",\"hook\":{\"prompt\":\"Nineteen policymakers each plot a dot for the year-end rate. One of them moves a dot up by 25 bp. Can the median change?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"yes\",\"label\":\"Yes\",\"feedback\":\"Right, if that dot crosses the middle. Here one move takes the median from 4.25% to 4.50%.\"},{\"id\":\"no\",\"label\":\"No\",\"feedback\":\"It can. The median is the 10th of 19 dots, so one dot crossing the middle moves it.\"}],\"answer\":\"yes\"},\"compare\":\"You chose {yours}. With 19 dots, the median is the 10th. Move the right dot and the median jumps a full step: here from 4.25% to 4.50%.\",\"concept\":\"dot-plot\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"Find the median\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"3.75%\",\"value\":2,\"role\":\"neutral\"},{\"label\":\"4.00%\",\"value\":6,\"role\":\"neutral\"},{\"label\":\"4.25%\",\"value\":2,\"role\":\"accent\"},{\"label\":\"4.50%\",\"value\":7,\"role\":\"neutral\"},{\"label\":\"4.75%\",\"value\":2,\"role\":\"neutral\"}],\"unit\":\" dots\",\"steps\":[\"Count from the bottom: 2 dots at 3.75% and 6 at 4.00%. That's 8.\",\"2 more at 4.25% make 10. The 10th dot, the median, sits at 4.25%.\",\"Above it: 7 at 4.50% and 2 at 4.75%. Nineteen dots in all.\"]},\"text\":\"A synthetic LCB [[dot-plot]]: each dot is one participant's year-end rate. Markets watch the median, the 10th of 19 dots, and compare it with the path futures price.\",\"concept\":\"dot-plot\"},{\"kind\":\"worked\",\"title\":\"One dot moves\",\"lines\":[\"One participant moves a dot from 4.25% to 4.50%.\",\"New counts: 3.75% (2), 4.00% (6), 4.25% (1), 4.50% (8), 4.75% (2).\",\"Count up: 2, 8, 9, then 17.\",\"The 10th dot, the new median = ?\"],\"ask\":{\"answer\":4.5,\"tolerance\":0.001,\"unit\":\"%\",\"feedback\":[{\"value\":4.25,\"text\":\"Count again: only 9 dots now sit at 4.25% or below, so the 10th is at 4.50%.\"}],\"correct\":\"Right: 4.50%. One participant moved the median a full step.\"},\"after\":\"The median is fragile when dots bunch on both sides of it. Read the whole distribution, not just the middle.\",\"concept\":\"dot-plot\"},{\"kind\":\"explain\",\"title\":\"Forecasts, not promises\",\"text\":\"Each dot is a conditional forecast: where that participant sees rates if their own outlook comes true. Central banks stress that the dots are not a commitment, and their record as predictions is mixed (evidence C). The long-run dot is an estimate of the [[neutral-rate]]: the rate that neither speeds up nor slows down the economy.\"},{\"kind\":\"predict\",\"title\":\"Dots against the price\",\"prompt\":\"The median dot rises 25 bp, from 4.25% to 4.50%. LRF had already priced a year-end rate of 4.50%. How much does LB2 move?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"big\",\"label\":\"Up sharply: the median rose 25 bp\",\"feedback\":\"A 25 bp higher median sounds big, but the market had already priced 4.50%. Nothing new arrived.\"},{\"id\":\"little\",\"label\":\"Little: the new median was already priced\",\"feedback\":\"Right.\"},{\"id\":\"down\",\"label\":\"Down: the market sells the news\",\"feedback\":\"Yields fall on a dovish surprise. This one matched the price.\"}],\"answer\":\"little\"},\"reveal\":\"Little. The dots caught up with the price. Had LRF priced 4.25%, the same dots would have added 25 bp to the expected path, and LB2 would have risen visibly. Compare the dots with the priced path (3.7.2), never on their own.\",\"concept\":\"dot-plot\"},{\"kind\":\"match\",\"title\":\"Three kinds of guidance\",\"prompt\":\"Sort each line of synthetic LCB guidance by its kind.\",\"pairs\":[{\"left\":\"'Rates will stay at this level at least until the middle of next year.'\",\"right\":\"Calendar\",\"wrong\":\"A date makes it calendar guidance.\"},{\"left\":\"'No hike while unemployment is above 5.50%.'\",\"right\":\"Threshold\",\"wrong\":\"A level in the data that must be crossed makes it threshold guidance.\"},{\"left\":\"'The Committee will be patient.'\",\"right\":\"Qualitative\",\"wrong\":\"No date and no number: qualitative guidance.\"},{\"left\":\"'Future decisions will be data dependent.'\",\"right\":\"Qualitative\",\"wrong\":\"No date and no number: qualitative guidance.\"}],\"columns\":[\"Guidance\",\"Kind\"],\"correct\":\"Right. The more specific the guidance, the harder the repricing when the bank walks away from it.\",\"concept\":\"forward-guidance\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Plan the [[press-conference]] before it starts. Its headlines can whipsaw price for 30 to 60 minutes: a hawkish line, then a softer answer, then a correction. And [[forward-guidance]] is not a promise: when a bank abandons it, the repricing is violent, because positions were built on it.\"},{\"kind\":\"predict\",\"title\":\"Your turn: move one dot\",\"prompt\":\"Back to the first plot: 2, 6, 2, 7 and 2 dots from 3.75% to 4.75%. Which single move takes the median from 4.25% to 4.50%?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"A 4.75% dot up to 5.00%\",\"feedback\":\"It was already above the median. Moving it further changes nothing in the middle.\"},{\"id\":\"b\",\"label\":\"A 4.00% dot up to 4.25%\",\"feedback\":\"Then 10 dots still sit at 4.25% or below, so the 10th stays at 4.25%.\"},{\"id\":\"c\",\"label\":\"A 3.75% dot up to 4.50%\",\"feedback\":\"Right.\"},{\"id\":\"d\",\"label\":\"A 4.50% dot up to 4.75%\",\"feedback\":\"It moves from above the median to further above. The 10th dot stays at 4.25%.\"}],\"answer\":\"c\"},\"reveal\":\"Even the lowest dot does it. Once it jumps above the middle, only 9 dots sit at 4.25% or below, so the 10th is at 4.50%. Any one dot that crosses from 4.25% or below to 4.50% or above moves the median.\",\"concept\":\"dot-plot\"},{\"kind\":\"fields\",\"title\":\"Your press-conference plan\",\"prompt\":\"Write your rule for the press conference now, before any decision day. The statement comes at 14:00; the conference starts at 14:30 and can whipsaw for an hour.\",\"fields\":[{\"id\":\"wait\",\"label\":\"No new orders until __ minutes after the conference starts\",\"kind\":\"stepper\",\"min\":0,\"max\":90,\"step\":15,\"unit\":\"min\",\"default\":0},{\"id\":\"guidance\",\"label\":\"If the bank drops its guidance, I\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. close positions that relied on it, then wait for normal spreads\",\"required\":true}],\"valid\":{\"field\":\"wait\",\"gte\":30},\"feedback\":[{\"when\":{\"field\":\"wait\",\"lt\":30},\"text\":\"Headlines can whipsaw for 30 to 60 minutes. Wait at least 30 before any new order.\"}],\"correct\":\"Saved. Decided now, while nothing is moving.\",\"concept\":\"second-move\"}],\"check\":[\"q-3.7.4-1\",\"q-3.7.4-2\",\"q-3.7.4-3\"],\"recap\":{\"takeaways\":[\"The median is the 10th of 19 dots; one dot crossing the middle can move it 25 bp.\",\"Dots move prices only where they differ from the priced path. Plan the press conference in advance.\",\"Guidance comes as a date, a threshold or a word; abandoned guidance reprices violently.\"]}},\"3.7.5\":{\"unit\":\"3.7\",\"courseId\":\"3.7.5\",\"hook\":{\"prompt\":\"LB10 yields 4.50%: a 3.60% expected path of policy rates plus a 0.90% term premium. The LCB announces large bond purchases. Which part falls most?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"path\",\"label\":\"The expected path\",\"feedback\":\"Bond buying signals rates staying low for longer, so the path dips. But the purchases act first on the premium.\"},{\"id\":\"premium\",\"label\":\"The term premium\",\"feedback\":\"Right.\"},{\"id\":\"equal\",\"label\":\"Both, equally\",\"feedback\":\"The split is debated for real programmes. In the LCB's case, most of the effect lands on the premium.\"}],\"answer\":\"premium\"},\"compare\":\"You chose {yours}. Buying long bonds takes risk off the market, so investors accept a smaller term premium; the path dips through signalling. Here the premium falls 0.50 and the path 0.10.\",\"concept\":\"qe-qt\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"Synthetic QE, in two parts\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Path, before\",\"value\":3.6,\"role\":\"neutral\"},{\"label\":\"Premium, before\",\"value\":0.9,\"role\":\"neutral\"},{\"label\":\"Path, after\",\"value\":3.5,\"role\":\"accent\"},{\"label\":\"Premium, after\",\"value\":0.4,\"role\":\"accent\"}],\"unit\":\"%\",\"steps\":[\"Before: LB10 at 4.50% = 3.60% expected path + 0.90% term premium.\",\"After the QE announcement: path 3.50%, premium 0.40%. LB10: 3.90%.\"]},\"text\":\"Synthetic numbers. [[quantitative-easing|QE]] works mainly through the term premium, the extra yield investors want for holding long bonds, and partly by signalling a lower path. Here LB10 falls 0.60 points: 0.50 from the premium, 0.10 from the path.\",\"concept\":\"qe-qt\"},{\"kind\":\"explain\",\"title\":\"What the estimates say\",\"text\":\"For real QE programmes, central-bank staff estimates put the drop in 10-year term premia at roughly a percentage point over several rounds, with part of it through signalling (evidence B; estimates vary). [[quantitative-tightening|QT]] is not the mirror image: runoff is slow and pre-announced, and its estimated effects are smaller and disputed (evidence C).\"},{\"kind\":\"explain\",\"title\":\"Caps and pegs\",\"text\":\"[[yield-curve-control|Yield curve control]] caps a long yield: the bank buys whatever bonds it must to hold it. Japan's central bank capped its 10-year yield for years. A cap or a [[currency-peg]] keeps its target calm and stores the pressure elsewhere: in the bank's purchases, other maturities, the currency. An exit can release it at once, as a gap.\"},{\"kind\":\"predict\",\"title\":\"Synthetic replay: the pressure gauge\",\"prompt\":\"The LCB caps LB10 at 1.00%, so LBND, a 10-year zero-coupon bond, can't fall below 90.53. Each week the LCB must buy more to hold the cap. When does a position that relies on the cap stop making sense?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"exit\",\"label\":\"When the LCB announces an exit\",\"feedback\":\"By then it's too late: the exit announcement is the gap.\"},{\"id\":\"pressure\",\"label\":\"When the purchases needed to hold it keep rising\",\"feedback\":\"Right.\"},{\"id\":\"never\",\"label\":\"Never: the cap protects the price\",\"feedback\":\"The cap protects the price only while the bank keeps paying for it.\"}],\"answer\":\"pressure\"},\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":90.62,\"h\":90.7,\"l\":90.56,\"c\":90.6},{\"o\":90.6,\"h\":90.66,\"l\":90.54,\"c\":90.58},{\"o\":90.58,\"h\":90.64,\"l\":90.53,\"c\":90.55},{\"o\":90.55,\"h\":90.61,\"l\":90.53,\"c\":90.57},{\"o\":90.57,\"h\":90.6,\"l\":90.53,\"c\":90.54},{\"o\":90.54,\"h\":90.58,\"l\":90.53,\"c\":90.55},{\"o\":90.55,\"h\":90.57,\"l\":90.53,\"c\":90.53},{\"o\":90.53,\"h\":90.56,\"l\":90.53,\"c\":90.54},{\"o\":90.54,\"h\":90.55,\"l\":90.53,\"c\":90.53},{\"o\":90.53,\"h\":90.54,\"l\":90.53,\"c\":90.53},{\"o\":86.17,\"h\":86.6,\"l\":85.9,\"c\":86.3},{\"o\":86.3,\"h\":86.7,\"l\":86.05,\"c\":86.45}],\"visible\":10},\"steps\":[{\"text\":\"LBND sits on 90.53 for ten sessions: the cap holds LB10 at 1.00%.\",\"layers\":[{\"kind\":\"level\",\"price\":90.53,\"role\":\"support\",\"label\":\"CAP · LB10 1.00%\"}]},{\"text\":\"The cap goes. LBND opens at 86.17, LB10 at 1.50%: 4.8% lower, past any stop.\",\"visible\":12,\"layers\":[{\"kind\":\"marker\",\"index\":10,\"at\":\"open\",\"label\":\"EXIT\",\"role\":\"down\"},{\"kind\":\"level\",\"price\":86.17,\"role\":\"neutral\",\"label\":\"LB10 1.50%\"}]}]},\"reveal\":\"Rising purchases mean the cap costs the bank more each week, and an exit gets likelier. When it comes, it comes as a gap: LB10 jumps from 1.00% to 1.50%, and LBND opens at 86.17, 4.8% lower. Nothing trades in between.\",\"concept\":\"yield-curve-control\"},{\"kind\":\"match\",\"title\":\"The warning ladder\",\"prompt\":\"Before intervening, currency officials usually escalate their words. Match each synthetic phrase to its step.\",\"pairs\":[{\"left\":\"'We are watching currency moves closely.'\",\"right\":\"Step 1: watching\",\"wrong\":\"Watching is the mildest step: attention, no threat.\"},{\"left\":\"'Recent moves are one-sided and speculative.'\",\"right\":\"Step 2: naming the problem\",\"wrong\":\"Calling moves one-sided or speculative names the problem: step 2.\"},{\"left\":\"'We will not rule out any options.'\",\"right\":\"Step 3: options open\",\"wrong\":\"Not ruling out options hints at action: step 3.\"},{\"left\":\"'We stand ready to take decisive action.'\",\"right\":\"Step 4: ready to act\",\"wrong\":\"Readiness for decisive action is the last step before intervention.\"}],\"columns\":[\"Phrase\",\"Step\"],\"correct\":\"Right. After step 4, intervention can come at any hour, often when markets are thin.\",\"concept\":\"fx-intervention\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"An [[fx-intervention]] can move a currency a few percent within minutes, and the move often fades if rate differentials don't change (evidence C). If you hold a [[carry]] position in that currency, size it for the jump, not for the calm before it.\"},{\"kind\":\"fields\",\"title\":\"Your exit rule, before the session\",\"prompt\":\"The simulator's cap-pressure gauge runs from 0 to 100: the share of all LBND selling the LCB must absorb to hold the cap. Set now the level at which you cut a position that relies on it.\",\"fields\":[{\"id\":\"cut\",\"label\":\"I cut the position when the gauge passes\",\"kind\":\"stepper\",\"min\":10,\"max\":100,\"step\":10,\"default\":100},{\"id\":\"why\",\"label\":\"Why a stop doesn't protect this position\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. an exit gaps the price past any stop\",\"required\":true}],\"valid\":{\"field\":\"cut\",\"lte\":80},\"feedback\":[{\"when\":{\"field\":\"cut\",\"gt\":80},\"text\":\"At {cut}, the bank is absorbing nearly all the selling: the exit may already be under way. Pick a level you'd act on early.\"}],\"correct\":\"Saved. The moment of the break isn't graded; acting on your own rule is.\",\"concept\":\"yield-curve-control\"}],\"task\":{\"widget\":\"position-size\",\"goal\":\"You hold LBND at 90.53 because the cap 'protects' it. If the cap breaks, LBND opens at 86.17: the widget's stop. Type the most units for which a break costs at most 1% of the account.\",\"start\":{\"account\":10000,\"riskPct\":1,\"entry\":90.53,\"stop\":86.17,\"units\":30},\"locked\":[\"account\",\"riskPct\",\"entry\",\"stop\"],\"hidden\":[\"simpleQty\",\"qty\"],\"success\":{\"all\":[{\"field\":\"units\",\"eq\":22},{\"field\":\"stop\",\"eq\":86.17}]},\"feedback\":[{\"when\":{\"field\":\"units\",\"eq\":23},\"text\":\"23 units lose 100.28 on price alone and 102.33 with commissions: over 100.00.\"},{\"when\":{\"field\":\"units\",\"gt\":23},\"text\":\"{units} units would lose {lossAtStop:2} at the break, over 100.00.\"},{\"when\":{\"field\":\"units\",\"lt\":22},\"text\":\"{units} units fit, but more would too. Find the most that does.\"}],\"correct\":\"Right. 22 units lose 97.87 at the break; 23 would lose 102.33. A stop above 86.17 wouldn't change that: nothing trades in between.\",\"hints\":[\"The loss at the break is units × (90.53 − 86.17), plus both commissions.\",\"Each unit loses 4.36 in the gap. 100.00 ÷ 4.36 is just under 23.\",\"Check 22 and 23 with the commissions.\"],\"showMe\":{\"units\":22},\"concept\":\"yield-curve-control\"},\"check\":[\"q-3.7.5-1\",\"q-3.7.5-2\",\"q-3.7.5-3\"],\"recap\":{\"takeaways\":[\"QE works mainly through the term premium; QT is slower and weaker, not its mirror image.\",\"Caps and pegs store pressure. When they go, price gaps: size for the break, not the calm.\",\"Intervention usually follows a ladder of warnings: watching, naming, options open, ready to act.\"]}},\"3.7.6\":{\"unit\":\"3.7\",\"courseId\":\"3.7.6\",\"hook\":{\"prompt\":\"A buy stop 0.40 above price, a sell stop 0.40 below, linked as OCO. Can this straddle lose if the market moves a lot?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"yes\",\"label\":\"Yes\",\"feedback\":\"Right. A spike can fill one side, then reverse into your protective stop.\"},{\"id\":\"no\",\"label\":\"No: a big move pays one side\",\"feedback\":\"A big move fills one side, but if it reverses you're stopped out, with slippage on both fills.\"}],\"answer\":\"yes\"},\"compare\":\"You chose {yours}. It can lose, and often does: the spike fills one side with slippage, the reversal stops it out, and OCO has already cancelled the other side.\",\"concept\":\"news-straddle\"},\"learn\":[{\"kind\":\"figure\",\"title\":\"A straddle, filled and stopped\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.06,\"l\":99.94,\"c\":100.02},{\"o\":100.02,\"h\":100.08,\"l\":99.96,\"c\":99.98},{\"o\":99.98,\"h\":100.04,\"l\":99.92,\"c\":100},{\"o\":100,\"h\":100.06,\"l\":99.96,\"c\":100.04},{\"o\":100.04,\"h\":100.08,\"l\":99.98,\"c\":100},{\"o\":100,\"h\":100.9,\"l\":99.98,\"c\":100.7},{\"o\":100.7,\"h\":100.8,\"l\":100.3,\"c\":100.4},{\"o\":100.4,\"h\":100.46,\"l\":99.8,\"c\":99.9},{\"o\":99.9,\"h\":100,\"l\":99.5,\"c\":99.6},{\"o\":99.6,\"h\":99.76,\"l\":99.44,\"c\":99.7}],\"visible\":5},\"steps\":[{\"text\":\"Before the release: buy stop at 100.40, sell stop at 99.60, linked as OCO.\",\"layers\":[{\"kind\":\"level\",\"price\":100.4,\"role\":\"entry\",\"label\":\"BUY STOP 100.40\"},{\"kind\":\"level\",\"price\":99.6,\"role\":\"neutral\",\"label\":\"SELL STOP 99.60 (OCO)\"}]},{\"text\":\"The headline spikes LABX. The buy stop fills at 100.55; OCO cancels the sell stop.\",\"visible\":7,\"layers\":[{\"kind\":\"marker\",\"index\":5,\"price\":100.55,\"label\":\"FILL 100.55\",\"role\":\"accent\"},{\"kind\":\"level\",\"price\":100,\"role\":\"stop\",\"label\":\"STOP 100.00\"}]},{\"text\":\"The details reverse the move. Your protective stop at 100.00 fills at 99.90.\",\"visible\":10,\"layers\":[{\"kind\":\"marker\",\"index\":7,\"price\":99.9,\"label\":\"EXIT 99.90\",\"role\":\"down\"}]}]},\"text\":\"Illustration, one-minute mids. A [[news-straddle]] pays the news spread twice: once going in on the spike, once going out on the reversal.\",\"concept\":\"news-straddle\"},{\"kind\":\"worked\",\"title\":\"The straddle's receipt\",\"lines\":[\"100 units. The buy stop at 100.40 filled at 100.55: 0.15 of [[slippage]].\",\"The protective stop at 100.00 filled at 99.90.\",\"Price: (99.90 − 100.55) × 100 = −65.00.\",\"Commissions: 5.03 in (on 10,055.00), 5.00 out (on 9,990.00).\",\"Result = ?\"],\"ask\":{\"answer\":-75.03,\"tolerance\":0.01,\"unit\":\"vUSD\",\"feedback\":[{\"value\":-65,\"text\":\"That's price alone. Subtract both commissions: 5.03 and 5.00.\"},{\"value\":75.03,\"text\":\"Right size, wrong sign: it's a loss, −75.03.\"},{\"value\":-50.02,\"text\":\"That assumes fills at your own levels. The spike and the reversal each cost slippage.\"}],\"correct\":\"Right: −75.03. Filled at your own levels, it would have been −50.02.\"},\"after\":\"Slippage on the two fills cost 25.01 more: half as much again as the loss at your own levels. In the Arena's unexpected-event scenario, log what your fills actually cost.\",\"concept\":\"news-straddle\"},{\"kind\":\"predict\",\"title\":\"Simulator setting: when did fading work?\",\"prompt\":\"Across 50 synthetic events, the chance that a spike retraces follows hidden rules of the generator. When did fading the first spike pay, after costs?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"big\",\"label\":\"After big surprises, |z| above 2\",\"feedback\":\"Big, clean surprises tended to keep going in the simulator. Fading them lost.\"},{\"id\":\"small\",\"label\":\"After small surprises with conflicting details\",\"feedback\":\"Right.\"},{\"id\":\"always\",\"label\":\"Always: first spikes overshoot\",\"feedback\":\"Not here. Fades of large, clean surprises lost after costs.\"},{\"id\":\"never\",\"label\":\"Never\",\"feedback\":\"In this generator fades paid in one narrow case: small surprises with mixed details.\"}],\"answer\":\"small\"},\"reveal\":\"Only when |z| was under 1 and the details disagreed. That's a rule of this generator, not a fact about real markets. In real markets, [[fade|fading]] the spike is practitioner lore: [[evidence-grade|evidence grade]] D.\",\"concept\":\"spike-fade\"},{\"kind\":\"explain\",\"title\":\"The option straddle\",\"text\":\"A straddle can also be built with options: buy a call and a put. You pay for the move the market expects. If options price a 4% move and the event delivers 3%, the straddle loses, as implied volatility collapses after the event. Buying options before events rates evidence C. Details in 3.8 and 4.1.\"},{\"kind\":\"figure\",\"title\":\"Same 30 events, six policies\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Flat\",\"value\":0,\"role\":\"neutral\"},{\"label\":\"Reduce\",\"value\":1.2,\"role\":\"up\"},{\"label\":\"Second move\",\"value\":2.4,\"role\":\"up\"},{\"label\":\"Fade\",\"value\":-1.8,\"role\":\"down\"},{\"label\":\"Surprise trade\",\"value\":-3.6,\"role\":\"down\"},{\"label\":\"Straddle\",\"value\":-6.3,\"role\":\"down\"}],\"unit\":\"R\",\"steps\":[\"Flat: 0R, nothing risked. Reduce: +1.2R from small positions held through events.\",\"Second move: +2.4R, the best run. Fading spikes: −1.8R.\",\"Instant surprise trades and straddles paid the news spread on every event.\"]},\"text\":\"One simulator run: the same 30 synthetic events for every policy, 1% risk per event, results after costs. It illustrates the comparison; it is not a result about real markets.\",\"concept\":\"news-policy\"},{\"kind\":\"worked\",\"title\":\"Is +2.4R real?\",\"lines\":[\"Second move: +2.4R over 30 events.\",\"Results per event vary with a standard deviation of 1.10R.\",\"Standard error: 1.10 ÷ √30 = 0.20R.\",\"Expectancy per event: 2.4 ÷ 30 = ?\"],\"ask\":{\"answer\":0.08,\"tolerance\":0.001,\"unit\":\"R\",\"feedback\":[{\"value\":2.4,\"text\":\"That's the total. Divide it by the 30 events.\"}],\"correct\":\"Right: +0.08R per event.\"},\"after\":\"A 95% interval is about 0.08 ± 2 × 0.20: from −0.32R to +0.48R. It includes zero, so 30 events can't tell this policy from flat. Report N and the interval with every result.\",\"concept\":\"expectancy\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"The simulator's winner depends on its settings, such as the hidden rule that made fades pay only at |z| under 1. What transfers is the method: same events, same costs, sample size stated, compared with flat.\"},{\"kind\":\"fields\",\"title\":\"Choose before you run\",\"prompt\":\"Your next 30 synthetic releases in the Arena. Pick one policy, and its limits, before the first one. You'll judge it on the process, not the profit.\",\"fields\":[{\"id\":\"policy\",\"label\":\"My policy for all 30 events\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"flat, reduce, trade the surprise, fade, straddle or second move\",\"required\":true},{\"id\":\"risk\",\"label\":\"Risk per event, gap scenario included\",\"kind\":\"stepper\",\"min\":0.25,\"max\":3,\"step\":0.25,\"unit\":\"%\",\"default\":2},{\"id\":\"drop\",\"label\":\"The result that would make me drop it\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. net expectancy below zero after 30 events, reported with N and interval\",\"required\":true}],\"valid\":{\"field\":\"risk\",\"lte\":1},\"feedback\":[{\"when\":{\"field\":\"risk\",\"gt\":1},\"text\":\"{risk}% per event is over the 1% limit. Size for the gap scenario, not for the stop.\"}],\"correct\":\"Saved before the run. Report the net expectancy with N, next to flat's zero.\",\"concept\":\"news-policy\"}],\"check\":[\"q-3.7.6-1\",\"q-3.7.6-2\",\"q-3.7.6-3\"],\"recap\":{\"takeaways\":[\"A straddle can fill on the spike and stop out on the reversal: −75.03 on 100 units.\",\"Fades paid in the simulator only on small, mixed surprises. In real markets they rate D.\",\"Compare policies on the same events, after costs, against flat, with N and the interval.\"]}},\"3.7.7\":{\"unit\":\"3.7\",\"courseId\":\"3.7.7\",\"hook\":{\"prompt\":\"In the original study, how much did a broad US stock index gain on average in the 24 hours before scheduled Fed announcements?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":100,\"step\":1,\"unit\":\"bp\",\"start\":10,\"answer\":49,\"tolerance\":10,\"feedback\":[{\"from\":0,\"to\":15,\"text\":\"Much more. The study found about 49 bp in a single day before each announcement.\"},{\"from\":16,\"to\":38,\"text\":\"Higher. The study found 49 bp on average in those 24 hours.\"},{\"from\":39,\"to\":59,\"text\":\"About right: 49 bp.\"},{\"from\":60,\"to\":100,\"text\":\"Lower: 49 bp, still remarkable for a single day.\"}]},\"compare\":\"You said {yours}. The study found 49 bp on average, in a sample starting in 1994: a large share of the period's stock returns, earned in a few days a year.\",\"concept\":\"pre-event-drift\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"The finding\",\"text\":\"A [[pre-announcement-drift]]: in a sample starting in 1994, a broad US stock index rose 49 bp on average in the 24 hours before scheduled Fed announcements, a large share of its excess return over the period. Why is still debated. Evidence B: strong in the original sample, with caution after publication.\"},{\"kind\":\"worked\",\"title\":\"How many events?\",\"lines\":[\"A synthetic drift: +0.10% per event, with a standard deviation of 1.00%.\",\"t = drift × √N ÷ SD = 0.10 × √N ÷ 1.00.\",\"For t = 2: √N = 2 × 1.00 ÷ 0.10 = 20.\",\"N = ?\"],\"ask\":{\"answer\":400,\"tolerance\":0,\"unit\":\"events\",\"feedback\":[{\"value\":20,\"text\":\"That's √N. Square it.\"},{\"value\":40,\"text\":\"√N is 20, so N = 20 × 20.\"}],\"correct\":\"Right: 400 events.\"},\"after\":\"At 8 meetings a year, 400 events take 50 years. A small drift in a noisy market needs a long history before it stands out from the noise of a small [[sample-size|sample]].\",\"concept\":\"sample-size\"},{\"kind\":\"predict\",\"title\":\"Forty events in\",\"prompt\":\"After 40 synthetic events, the average drift is +0.12%, with a standard deviation of 1.00%. Is the drift real?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"yes\",\"label\":\"Yes: it's positive and above 0.10%\",\"feedback\":\"Positive, but noisy. The standard error is 0.16%, larger than the drift itself.\"},{\"id\":\"cant\",\"label\":\"Can't tell yet: the interval includes zero\",\"feedback\":\"Right.\"},{\"id\":\"no\",\"label\":\"No: it's too small to matter\",\"feedback\":\"Small drifts can matter. This one just can't be told from zero yet.\"}],\"answer\":\"cant\"},\"reveal\":\"Standard error: 1.00 ÷ √40 = 0.16. The 95% interval, 0.12 ± 0.32, runs from −0.20% to +0.44%. It includes zero: forty events can't confirm the drift, and can't rule it out.\",\"concept\":\"sample-size\"},{\"kind\":\"explain\",\"title\":\"Buy the rumour, sell the news\",\"text\":\"[[buy-the-rumour-sell-the-news|Buy the rumour, sell the news]]: price runs up into an expected good event, then falls when it's confirmed, as traders who bought early take profits. It happens often enough to have a name, but not reliably enough to trade blindly: evidence C.\"},{\"kind\":\"predict\",\"title\":\"Heavy or washed out?\",\"prompt\":\"Five synthetic news reactions this week. Good news: −0.4%. Good news: −0.2%. Bad news: −0.9%. Good news: flat. Bad news: −0.6%. Is the market heavy or washed out?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"heavy\",\"label\":\"Heavy: crowded long, with little buying left\",\"feedback\":\"Right.\"},{\"id\":\"washed\",\"label\":\"Washed out: the sellers are done\",\"feedback\":\"A washed-out market shrugs off bad news and rallies on good. This one falls on both.\"},{\"id\":\"none\",\"label\":\"No reading: reactions are random\",\"feedback\":\"One reaction tells you little. Five that lean the same way are a hint: weak, but useful.\"}],\"answer\":\"heavy\"},\"reveal\":\"Heavy. A market that can't rally on good news, and falls hard on bad, is likely already long: buyers are in, sellers are waiting. A reaction tell is a discretionary read, evidence D. Check it against positioning data when you have it.\",\"concept\":\"market-tell\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Published anomalies fade. One large study found that predictors from published research earned 26% less [[out-of-sample|out of sample]] and 58% less after publication. Expect any famous drift to weaken once everyone knows about it.\"},{\"kind\":\"predict\",\"title\":\"The peek\",\"prompt\":\"You test a drift by checking after every 10 events, and you'll stop the first time p falls below 0.05. Is that a fair test?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"fair\",\"label\":\"Yes: p below 0.05 is significant\",\"feedback\":\"Each look is another chance for luck to cross the line. Many looks push false alarms far above 5%.\"},{\"id\":\"unfair\",\"label\":\"No: stopping at the first good look inflates false findings\",\"feedback\":\"Right.\"},{\"id\":\"more\",\"label\":\"Yes, and peeking more often is even better\",\"feedback\":\"More looks mean more chances for noise to cross 0.05 by luck.\"}],\"answer\":\"unfair\"},\"reveal\":\"That's [[optional-stopping]]. Every look is another chance for noise to cross 0.05, so a drift that isn't there can 'pass'. Fix the number of events, or the stopping rule, before you start.\",\"concept\":\"sample-size\"},{\"kind\":\"fields\",\"title\":\"Your test plan\",\"prompt\":\"Write the test before you see a single event. Drift +0.10%, standard deviation 1.00%: you worked out how many events t = 2 needs.\",\"fields\":[{\"id\":\"n\",\"label\":\"I judge the drift after __ events, no earlier\",\"kind\":\"stepper\",\"min\":10,\"max\":500,\"step\":10,\"default\":50},{\"id\":\"report\",\"label\":\"My conclusion will state\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"N, the average, the 95% interval, and whether it excludes zero\",\"required\":true}],\"valid\":{\"field\":\"n\",\"gte\":400},\"feedback\":[{\"when\":{\"field\":\"n\",\"lt\":400},\"text\":\"At {n} events the interval is still wider than the drift, so a 'yes' would likely be luck. You need about 400.\"}],\"correct\":\"Saved. N is fixed in advance, so no peek can fool you.\",\"concept\":\"sample-size\"}],\"check\":[\"q-3.7.7-1\",\"q-3.7.7-2\",\"q-3.7.7-3\"],\"recap\":{\"takeaways\":[\"The documented pre-Fed drift was 49 bp a day; published anomalies usually shrink afterwards.\",\"A 0.10% drift with a 1.00% standard deviation needs about 400 events to reach t = 2.\",\"Falling on good news hints at a heavy, crowded market: a weak tell, grade D.\"]}},\"3.7.8\":{\"unit\":\"3.7\",\"courseId\":\"3.7.8\",\"hook\":{\"prompt\":\"Your stop is 0.40 away. The market reopens 15% lower. Where does the stop fill?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"at\",\"label\":\"At the stop\",\"feedback\":\"A triggered stop becomes a market order. Nothing traded at your level.\"},{\"id\":\"near\",\"label\":\"Near the stop\",\"feedback\":\"Near would need prices between the stop and the reopening. There were none.\"},{\"id\":\"first\",\"label\":\"At the first available price\",\"feedback\":\"Right.\"}],\"answer\":\"first\"},\"compare\":\"You chose {yours}. A stop is an instruction, not a price: after a 15% gap, it sells at the first bid there is, far below its level.\",\"concept\":\"tail-event\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Historical case: a floor removed\",\"text\":\"**Historical case.** In January 2015 the Swiss National Bank dropped its 1.20 floor on EUR/CHF without warning. Quotes vanished: a [[liquidity-vacuum]]. The rate fell far below the floor within minutes, and stops filled far beyond their levels. Some traders ended up owing their brokers money, and at least one retail broker failed.\"},{\"kind\":\"explain\",\"title\":\"Historical case: the Flash Crash\",\"text\":\"**Historical case.** In the [[flash-crash|Flash Crash]] of 6 May 2010, a large automated sell order in US stock-index futures ran without regard to price or time. Liquidity evaporated; major US indexes fell several percent within minutes and recovered most of it that afternoon. Some stocks traded at absurd prices, down to a cent.\"},{\"kind\":\"worked\",\"title\":\"Synthetic replay: the peg breaks\",\"lines\":[\"LPEG has sat at its 120.00 floor for 40 sessions. You're long 800 at 120.20, on a leveraged account.\",\"Position value: 96,160 vUSD, about 9.6 times your 10,000. Stop at 119.80: a planned risk of 320, 3.2%.\",\"The floor goes. LPEG reopens at 102.00, 15.1% lower, and your stop sells there.\",\"Price loss: 800 × (120.20 − 102.00) = ?\"],\"ask\":{\"answer\":14560,\"tolerance\":0.5,\"unit\":\"vUSD\",\"feedback\":[{\"value\":320,\"text\":\"That's the plan, at 119.80. The stop sold at 102.00.\"},{\"value\":1456,\"text\":\"Check the zeros: 800 × 18.20.\"}],\"correct\":\"Right: 14,560.00, more than the whole account.\"},\"after\":\"Without [[negative-balance-protection]], your balance is −4,560.00: you owe the broker. With it, the loss stops at your 10,000.00. Either way the account is gone: leverage turned a 3.2% plan into a 146% loss.\",\"concept\":\"gap-risk\"},{\"kind\":\"worked\",\"title\":\"Size for the gap\",\"lines\":[\"Same entry, 120.20. Plan for a 15% gap: a reopening at 120.20 × 0.85 = 102.17.\",\"Loss per unit: 18.03, plus commissions on both fills.\",\"Budget: 1% of 10,000.00 = 100.00.\",\"Most whole units within 100.00 = ?\"],\"ask\":{\"answer\":5,\"tolerance\":0,\"unit\":\"units\",\"feedback\":[{\"value\":6,\"text\":\"6 units lose 108.18 on price and 108.86 with commissions: over 100.00.\"},{\"value\":250,\"text\":\"100.00 ÷ 0.40 sizes for the stop. In the gap, each unit loses 18.03.\"},{\"value\":192,\"text\":\"That sizes for the stop, with costs. In the gap, 192 units would lose 3,483.11.\"}],\"correct\":\"Right: 5 units lose 90.72 in the gap; 6 would lose 108.86.\"},\"after\":\"Five units at a 'safe' floor feels absurdly small. That feeling is the danger: sized for the stop, 192 units would lose 3,483.11 in the same gap. The gap you fear sets the size.\",\"concept\":\"position-sizing\"},{\"kind\":\"match\",\"title\":\"Rules and what they guard\",\"prompt\":\"Match each tail-risk rule to the danger it guards against.\",\"pairs\":[{\"left\":\"Leverage cap\",\"right\":\"A loss bigger than the account\",\"wrong\":\"Capping leverage caps what a single gap can take, even past your stop.\"},{\"left\":\"Size for the gap\",\"right\":\"A stop that gets skipped\",\"wrong\":\"Gap sizing assumes the stop fills at the reopening, and keeps that affordable.\"},{\"left\":\"Flat before big events and long closes\",\"right\":\"News and weekend gaps\",\"wrong\":\"Being flat is the only rule that removes the gap entirely.\"},{\"left\":\"Guaranteed stop, for a fee\",\"right\":\"A fill far from your price\",\"wrong\":\"A guaranteed stop fills at its level whatever the gap; you pay a premium for that.\"},{\"left\":\"Negative balance protection\",\"right\":\"Owing your broker money\",\"wrong\":\"It caps the loss at your deposit, but the deposit is still gone.\"}],\"columns\":[\"Rule\",\"Guards against\"],\"correct\":\"Right. No single rule covers everything; together they make a tail event survivable.\",\"concept\":\"tail-event\"},{\"kind\":\"predict\",\"title\":\"The guaranteed stop\",\"prompt\":\"Your broker offers a guaranteed stop at 119.80, for a fee per unit. LPEG reopens at 102.00. What do you lose per unit, before commissions?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"fee\",\"label\":\"0.40, plus the fee\",\"feedback\":\"Right.\"},{\"id\":\"full\",\"label\":\"18.20, like any stop\",\"feedback\":\"That's an ordinary stop. A guaranteed one fills at its level, whatever the gap.\"},{\"id\":\"none\",\"label\":\"Nothing: the broker pays\",\"feedback\":\"The broker takes the gap, but you still lose the 0.40 to your stop, plus the fee.\"}],\"answer\":\"fee\"},\"reveal\":\"0.40 plus the fee, whatever the gap: the broker takes the gap risk and charges you for it. Count the fee in every trade, and check which instruments and events your broker covers with a [[guaranteed-stop]].\",\"concept\":\"stop-loss-order\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Emergency central-bank moves, like a surprise rate cut between meetings, can read as relief or as panic. Which way markets take them can't be known in advance, only that the range will be wide. Size for the range, not for a direction.\"},{\"kind\":\"fields\",\"title\":\"Your tail-risk rules\",\"prompt\":\"Write the tail-risk rules for your plan. They apply to every position, before any event.\",\"fields\":[{\"id\":\"lev\",\"label\":\"Leverage cap\",\"kind\":\"stepper\",\"min\":1,\"max\":30,\"step\":1,\"unit\":\"×\",\"default\":10},{\"id\":\"gap\",\"label\":\"Most I lose in a 15% gap, % of the account\",\"kind\":\"stepper\",\"min\":0.5,\"max\":10,\"step\":0.5,\"unit\":\"%\",\"default\":5},{\"id\":\"events\",\"label\":\"Before big events and long market closes, I\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. go flat, or cut to the gap size\",\"required\":true},{\"id\":\"broker\",\"label\":\"Broker protections I've checked\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. negative balance protection: yes; guaranteed stops: fee per unit\",\"required\":false}],\"valid\":{\"all\":[{\"field\":\"lev\",\"lte\":5},{\"field\":\"gap\",\"lte\":2}]},\"feedback\":[{\"when\":{\"field\":\"lev\",\"gt\":5},\"text\":\"At {lev}×, a 15% gap takes most or all of the account. This course caps leverage at 5×; lower is better.\"},{\"when\":{\"field\":\"gap\",\"gt\":2},\"text\":\"{gap}% in a single gap is more than a bad week should cost. Keep it at 2% or less.\"}],\"correct\":\"Saved to your plan. These rules don't make tail events rare; they make them survivable.\",\"concept\":\"tail-event\"}],\"task\":{\"widget\":\"position-size\",\"goal\":\"A pegged pair has sat at its 120.00 floor for 40 sessions. Plan for a 15% gap from 120.20: the widget's stop is 102.17. Type the most units that lose at most 2% of the account.\",\"start\":{\"account\":10000,\"riskPct\":2,\"entry\":120.2,\"stop\":102.17,\"units\":20},\"locked\":[\"account\",\"riskPct\",\"entry\",\"stop\"],\"hidden\":[\"simpleQty\",\"qty\"],\"success\":{\"all\":[{\"field\":\"units\",\"eq\":11},{\"field\":\"stop\",\"eq\":102.17}]},\"feedback\":[{\"when\":{\"field\":\"units\",\"eq\":12},\"text\":\"12 units lose 216.36 on price and 217.71 with commissions: over 200.00.\"},{\"when\":{\"field\":\"units\",\"gt\":12},\"text\":\"{units} units would lose {lossAtStop:2} in the gap, over 200.00.\"},{\"when\":{\"field\":\"units\",\"lt\":11},\"text\":\"{units} units fit, but more would too. Find the most that does.\"}],\"correct\":\"Right: 11 units lose 199.57 in the gap. Put your real stop anywhere above 102.17 and that worst case doesn't change: the gap skips it.\",\"hints\":[\"In the gap, each unit loses 120.20 − 102.17 = 18.03, plus commissions.\",\"200.00 ÷ 18.03 is just over 11.\",\"Check 11 and 12 with the commissions.\"],\"showMe\":{\"units\":11},\"concept\":\"gap-risk\"},\"check\":[\"q-3.7.8-1\",\"q-3.7.8-2\",\"q-3.7.8-3\"],\"recap\":{\"takeaways\":[\"In a tail event quotes vanish, and stops fill at the first available price, far past their level.\",\"Size for the gap: 5 units at 1%, not 192. Know your loss with and without balance protection.\",\"Write tail rules in advance: a leverage cap, gap sizing, event exposure and broker protections.\"]}}}");
